Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by the incorrect retrieval of driver management data from the parent device of the current device, which could lead to NULL pointer dereferences if the parent device was not properly initialized or did not exist. This was a result of changes made in a previous commit that altered the expected device hierarchy.

Here is the patch:

 static struct vchiq_pagelist_info *
 create_pagelist(struct vchiq_instance *instance, char *buf, char __user *ubuf,
 		size_t count, unsigned short type)
 {
 	struct vchiq_drv_mgmt *drv_mgmt;
 	struct pagelist *pagelist;
 	struct vchiq_pagelist_info *pagelistinfo;
 	struct page **pages;
 	u32 *addrs;
 	unsigned int num_pages, offset, i, k;
 	int actual_pages;
 	size_t pagelist_size;
 	struct scatterlist *scatterlist, *sg;
 	int dma_buffers;
 	dma_addr_t dma_addr;

 	if (count >= INT_MAX - PAGE_SIZE)
 		return NULL;

-	drv_mgmt = dev_get_drvdata(instance->state->dev->parent);
+	drv_mgmt = dev_get_drvdata(instance->state->dev);

 	if (buf)
 		offset = (uintptr_t)buf & (PAGE_SIZE - 1);
 	else
 		offset = (uintptr_t)ubuf & (PAGE_SIZE - 1);
 	num_pages = DIV_ROUND_UP(count + offset, PAGE_SIZE);

 	if ((size_t)num_pages > (SIZE_MAX - sizeof(struct pagelist) -
 			 sizeof(struct vchiq_pagelist_info)) /
 			(sizeof(u32) + sizeof(pages[0]) +
 			 sizeof(struct scatterlist)))
 		return NULL;

 	pagelist_size = sizeof(struct pagelist) +
 			(num_pages * sizeof(u32)) +
 			(num_pages * sizeof(pages[0]) +
 			(num_pages * sizeof(struct scatterlist))) +
 			sizeof(struct vchiq_pagelist_info);

 	/* Allocate enough storage to hold the page pointers and the page
 	 * list
 	 */
 	pagelist = dma_alloc_coherent(instance->state->dev, pagelist_size, &dma_addr,
 				      GFP_KERNEL);

 	dev_dbg(instance->state->dev, "arm: %pK\n", pagelist);

 	if (!pagelist)
 		return NULL;

 	addrs		= pagelist->addrs;
 	pages		= (struct page **)(addrs + num_pages);
 	scatterlist	= (struct scatterlist *)(pages + num_pages);
 	pagelistinfo	= (struct vchiq_pagelist_info *)
 			  (scatterlist + num_pages);

 	pagelist->length = count;
 	pagelist->type = type;
 	pagelist->offset = offset;

 	/* Populate the fields of the pagelistinfo structure */
 	pagelistinfo->pagelist = pagelist;
 	pagelistinfo->pagelist_buffer_size = pagelist_size;
 	pagelistinfo->dma_addr = dma_addr;
 	pagelistinfo->dma_dir =  (type == PAGELIST_WRITE) ?
 				  DMA_TO_DEVICE : DMA_FROM_DEVICE;
 	pagelistinfo->num_pages = num_pages;
 	pagelistinfo->pages_need_release = 0;
 	pagelistinfo->pages = pages;
 	pagelistinfo->scatterlist = scatterlist;
 	pagelistinfo->scatterlist_mapped = 0;

 	if (buf) {
 		unsigned long length = count;
 		unsigned int off = offset;

 		for (actual_pages = 0; actual_pages < num_pages;
 		     actual_pages++) {
 			struct page *pg =
 				vmalloc_to_page((buf +
 						 (actual_pages * PAGE_SIZE)));
 			size_t bytes = PAGE_SIZE - off;

 			if (!pg) {
 				cleanup_pagelistinfo(instance, pagelistinfo);
 				return NULL;
 			}

 			if (bytes > length)
 				bytes = length;
 			pages[actual_pages] = pg;
 			length -= bytes;
 			off = 0;
 		}
 		/* do not try and release vmalloc pages */
 	} else {
 		actual_pages = pin_user_pages_fast((unsigned long)ubuf & PAGE_MASK, num_pages,
 						   type == PAGELIST_READ, pages);

 		if (actual_pages != num_pages) {
 			dev_dbg(instance->state->dev, "arm: Only %d/%d pages locked\n",
 				actual_pages, num_pages);

 			/* This is probably due to the process being killed */
 			if (actual_pages > 0)
 				unpin_user_pages(pages, actual_pages);
 			cleanup_pagelistinfo(instance, pagelistinfo);
 			return NULL;
 		}
 		 /* release user pages */
 		pagelistinfo->pages_need_release = 1;
 	}

 	/*
 	 * Initialize the scatterlist so that the magic cookie
 	 *  is filled if debugging is enabled
 	 */
 	sg_init_table(scatterlist, num_pages);
 	/* Now set the pages for each scatterlist */
 	for (i = 0; i < num_pages; i++)	{
 		unsigned int len = PAGE_SIZE - offset;

 		if (len > count)
 			len = count;
 		sg_set_page(scatterlist + i, pages[i], len, offset);
 		offset = 0;
 		count -= len;
 	}

 	dma_buffers = dma_map_sg(instance->state->dev,
 				 scatterlist,
 				 num_pages,
 				 pagelistinfo->dma_dir);

 	if (dma_buffers == 0) {
 		cleanup_pagelistinfo(instance, pagelistinfo);
 		return NULL;
 	}

 	pagelistinfo->scatterlist_mapped = 1;

 	/* Combine adjacent blocks for performance */
 	k = 0;
 	for_each_sg(scatterlist, sg, dma_buffers, i) {
 		u32 len = sg_dma_len(sg);
 		u32 addr = sg_dma_address(sg);

 		/* Note: addrs is the address + page_count - 1
 		 * The firmware expects blocks after the first to be page-
 		 * aligned and a multiple of the page size
 		 */
 		WARN_ON(len == 0);
 		WARN_ON(i && (i != (dma_buffers - 1)) && (len & ~PAGE_MASK));
 		WARN_ON(i && (addr & ~PAGE_MASK));
 		if (is_adjacent_block(addrs, addr, k))
 			addrs[k - 1] += ((len + PAGE_SIZE - 1) >> PAGE_SHIFT);
 		else
 			addrs[k++] = (addr & PAGE_MASK) |
 				(((len + PAGE_SIZE - 1) >> PAGE_SHIFT) - 1);
 	}

 	/* Partial cache lines (fragments) require special measures */
 	if ((type == PAGELIST_READ) &&
 	    ((pagelist->offset & (drv_mgmt->info->cache_line_size - 1)) ||
 	    ((pagelist->offset + pagelist->length) &
 	    (drv_mgmt->info->cache_line_size - 1)))) {
 		char *fragments;

 		if (down_interruptible(&drv_mgmt->free_fragments_sema)) {
 			cleanup_pagelistinfo(instance, pagelistinfo);
 			return NULL;
 		}

 		WARN_ON(!drv_mgmt->free_fragments);

 		down(&drv_mgmt->free_fragments_mutex);
 		fragments = drv_mgmt->free_fragments;
 		WARN_ON(!fragments);
 		drv_mgmt->free_fragments = *(char **)drv_mgmt->free_fragments;
 		up(&drv_mgmt->free_fragments_mutex);
 		pagelist->type = PAGELIST_READ_WITH_FRAGMENTS +
 			(fragments - drv_mgmt->fragments_base) / drv_mgmt->fragments_size;
 	}

 	return pagelistinfo;
 }

 static void
 free_pagelist(struct vchiq_instance *instance, struct vchiq_pagelist_info *pagelistinfo,
 	      int actual)
 {
 	struct vchiq_drv_mgmt *drv_mgmt;
 	struct pagelist *pagelist = pagelistinfo->pagelist;
 	struct page **pages = pagelistinfo->pages;
 	unsigned int num_pages = pagelistinfo->num_pages;

 	dev_dbg(instance->state->dev, "arm: %pK, %d\n", pagelistinfo->pagelist, actual);

-	drv_mgmt = dev_get_drvdata(instance->state->dev->parent);
+	drv_mgmt = dev_get_drvdata(instance->state->dev);

 	/*
 	 * NOTE: dma_unmap_sg must be called before the
 	 * cpu can touch any of the data/pages.
 	 */
 	dma_unmap_sg(instance->state->dev, pagelistinfo->scatterlist,
 		     pagelistinfo->num_pages, pagelistinfo->dma_dir);
 	pagelistinfo->scatterlist_mapped = 0;

 	/* Deal with any partial cache lines (fragments) */
 	if (pagelist->type >= PAGELIST_READ_WITH_FRAGMENTS && drv_mgmt->fragments_base) {
 		char *fragments = drv_mgmt->fragments_base +
 			(pagelist->type - PAGELIST_READ_WITH_FRAGMENTS) *
 			drv_mgmt->fragments_size;
 		int head_bytes, tail_bytes;

 		head_bytes = (drv_mgmt->info->cache_line_size - pagelist->offset) &
 			(drv_mgmt->info->cache_line_size - 1);
 		tail_bytes = (pagelist->offset + actual) &
 			(drv_mgmt->info->cache_line_size - 1);

 		if ((actual >= 0) && (head_bytes != 0)) {
 			if (head_bytes > actual)
 				head_bytes = actual;

 			memcpy_to_page(pages[0],
 				pagelist->offset,
 				fragments,
 				head_bytes);
 		}
 		if ((actual >= 0) && (head_bytes < actual) &&
 		    (tail_bytes != 0))
 			memcpy_to_page(pages[num_pages - 1],
 				(pagelist->offset + actual) &
 				(PAGE_SIZE - 1) & ~(drv_mgmt->info->cache_line_size - 1),
 				fragments + drv_mgmt->info->cache_line_size,
 				tail_bytes);

 		down(&drv_mgmt->free_fragments_mutex);
 		*(char **)fragments = drv_mgmt->free_fragments;
 		drv_mgmt->free_fragments = fragments;
 		up(&drv_mgmt->free_fragments_mutex);
 		up(&drv_mgmt->free_fragments_sema);
 	}

 	/* Need to mark all the pages dirty. */
 	if (pagelist->type != PAGELIST_WRITE &&
 	    pagelistinfo->pages_need_release) {
 		unsigned int i;

 		for (i = 0; i < num_pages; i++)
 			set_page_dirty(pages[i]);
 	}

 	cleanup_pagelistinfo(instance, pagelistinfo);
 }



